import { Transaction } from "../entities/transaction.entity.js";

export const TRANSACTION_REPOSITORY = Symbol("TRANSACTION_REPOSITORY");

export interface ITransactionRepository {
  /**
   * Ejecuta un depósito de manera atómica con Optimistic Locking.
   */
  processDeposit(
    depositId: string,
    accountId: string,
    amount: number,
  ): Promise<void>;

  /**
   * Ejecuta una transferencia entre cuentas de manera atómica con Optimistic Locking
   * y guarda el evento Outbox asociado.
   */
  processTransfer(transaction: Transaction): Promise<void>;

  getTransfersByUser(userId: string): Promise<Transaction[]>;

  /**
   * Obtiene los eventos en estado PENDING para procesar (Outbox Pattern)
   */
  getPendingOutboxEvents(): Promise<{ id: string, type: string, payload: any }[]>;

  /**
   * Marca un evento como publicado (Outbox Pattern)
   */
  markOutboxEventAsPublished(eventId: string): Promise<void>;
}
